SELECT sys_social_account.id, sys_social_account.type, sys_social_account.app_id, sys_social_account.app_secret, sys_social_account.redirect_url, sys_social_account.create_time, sys_social_account.update_time, sys_social_account.del_flag, sys_social_account.create_by, sys_social_account.update_by FROM sys_social_account AS sys_social_account
AND sys_social_account.del_flag ='0'
AND sys_social_account.app_id =#{query.appId}
AND sys_social_account.type =#{query.type}
